        "PageInformation": {
            "type": "object",
            "properties": {
                "pageInformationName": {},
                "pageInformationQnaPodEnabled": {},
                "pageInformationAltName": {},
                "pageInformationType": {}
            },
            "additionalProperties": false
        },
        "PageSize": {
            "type": "object",
            "properties": {
                "pageSizeTypes": {},
                "pageSizeWidth": {},
                "pageSizeHeight": {}
            },
            "additionalProperties": false
        },
        "Background": {
            "type": "object",
            "properties": {
                "color": {},
                "image": {},
                "transparency": {}
            },
            "additionalProperties": false
        },
        "DisplayArea": {
            "type": "object",
            "properties": {
                "verticalAlignment": {}
            },
            "additionalProperties": false
        },
        "OutspacePane": {
            "type": "object",
            "properties": {
                "backgroundColor": {},
                "transparency": {},
                "foregroundColor": {},
                "titleSize": {},
                "searchTextSize": {},
                "headerSize": {},
                "fontFamily": {},
                "border": {},
                "borderColor": {},
                "checkboxAndApplyColor": {},
                "inputBoxColor": {},
                "width": {}
            },
            "additionalProperties": false
        },
        "FilterCard": {
            "type": "object",
            "properties": {
                "backgroundColor": {},
                "transparency": {},
                "border": {},
                "borderColor": {},
                "foregroundColor": {},
                "textSize": {},
                "fontFamily": {},
                "inputBoxColor": {}
            },
            "additionalProperties": false
        },
        "PageRefresh": {
            "type": "object",
            "properties": {
                "show": {},
                "refreshType": {},
                "duration": {},
                "dialogLauncher": {},
                "measure": {},
                "checkEvery": {}
            },
            "additionalProperties": false
        },
        "PersonalizeVisual": {
            "type": "object",
            "properties": {
                "show": {},
                "perspectiveRef": {},
                "applyToAllPages": {}
            },
            "additionalProperties": false
        },
        "VisualInteraction": {
            "type": "object",
            "properties": {
                "source": {
                    "description": "Visual name that will be the source of user interaction (selecting data point for example).",
                    "type": "string"
                },
                "target": {
                    "description": "Visual name for the target of the interaction (selecting data point for example).",
                    "type": "string"
                },
                "type": {
                    "$ref": "#/definitions/VisualInteractionFilterType",
                    "description": "How should the interaction flow from source to target visual (as highlights, as filter, none)."
                }
            },
            "additionalProperties": false,
            "required": [
                "source",
                "target",
                "type"
            ]
        },
        "VisualInteractionFilterType": {
            "type": "string",
            "anyOf": [
                {
                    "const": "Default",
                    "description": "The target visual type determines if it should accept the interaction as a highlight or as a filter."
                },
                {
                    "const": "DataFilter",
                    "description": "Data point selection is added as a filter to the target visual."
                },
                {
                    "const": "HighlightFilter",
                    "description": "Data point selection is added as a highlight to the target visual."
                },
                {
                    "const": "NoFilter",
                    "description": "Data point selection is ignored by the target visual."
                }
            ]
        },
        "AutoPageGenerationConfig": {
            "type": "object",
            "properties": {
                "selectedFields": {
                    "description": "Data fields to use for the auto page generation",
                    "type": "array",
                    "items": {
                        "$ref": "../../semanticQuery/1.0.0/schema.json#/definitions/QueryExpressionContainer"
                    }
                },
                "visualContainerConfigurations": {
                    "description": "Visuals already on the page previously generated by the auto-config",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/QuickExploreVisualContainerConfig"
                    }
                },
                "layout": {
                    "description": "The specific layout chosen to render the auto-visuals",
                    "$ref": "#/definitions/QuickExploreLayoutContainer"
                }
            },
            "additionalProperties": false,
            "required": [
                "selectedFields",
                "visualContainerConfigurations"
            ]
        },
        "QuickExploreVisualContainerConfig": {
            "type": "object",
            "properties": {
                "name": {
                    "description": "Name of the visual - matches the name property in visual.json files",
                    "type": "string"
                },
                "fields": {
                    "description": "Specific data fields used to build this visual from the full set of selected fields",
                    "type": "array",
                    "items": {
                        "$ref": "../../semanticQuery/1.0.0/schema.json#/definitions/QueryExpressionContainer"
                    }
                }
            },
            "additionalProperties": false,
            "required": [
                "fields",
                "name"
            ]
        },
        "QuickExploreLayoutContainer": {
            "type": "object",
            "properties": {
                "related": {
                    "description": "A layout that has 1 hero visual and some related visuals",
                    "$ref": "#/definitions/QuickExploreRelatedLayout"
                },
                "combination": {
                    "description": "Layout that generates visuals purely based on combination of fields\nDeprecated: Use related layout instead.",
                    "$ref": "#/definitions/QuickExploreCombinationLayout"
                }
            },
            "additionalProperties": false
        },
        "QuickExploreRelatedLayout": {
            "type": "object",
            "properties": {
                "version": {
                    "default": 1,
                    "type": "number"
                },
                "dataTableName": {
                    "description": "If data table is shown, then the name of that visual",
                    "type": "string"
                }
            },
            "additionalProperties": false,
            "required": [
                "version"
            ]
        },
        "QuickExploreCombinationLayout": {
            "type": "object",
            "properties": {
                "version": {
                    "default": 1,
                    "type": "number"
                },
                "dataTableName": {
                    "description": "If data table is shown, then the name of that visual",
                    "type": "string"
                }
            },
            "additionalProperties": false,
            "required": [
                "version"
            ]
        },
        "Annotation": {
            "type": "object",
            "properties": {
                "name": {
                    "description": "Unique name for the annotation.",
                    "type": "string"
                },
                "value": {
                    "description": "A value for this annotation.",
                    "type": "string"
                }
            },
            "additionalProperties": false,
            "required": [
                "name",
                "value"
            ]
        }
    }
}

{
    "$id": "https://developer.microsoft.com/json-schemas/fabric/item/report/definition/visualContainer/2.0.0/schema.json",
    "$schema": "http://json-schema.org/draft-07/schema#",
    "title": "Visual container",
    "description": "Defines a single visual or visual group on a report page.",
    "type": "object",
    "properties": {
        "$schema": {
            "description": "Defines the schema to use for an item.",
            "type": "string",
            "const": "https://developer.microsoft.com/json-schemas/fabric/item/report/definition/visualContainer/2.0.0/schema.json"
        },
        "name": {
            "description": "A unique identifier for the visual across the whole page.",
            "maxLength": 50,
            "type": "string"
        },
        "position": {
            "$ref": "#/definitions/VisualContainerPosition",
            "description": "Defines where the visual is position on the page and how big it should be, along\nwith z-index (stacking) for that visual.\nAlso defines the order in which visuals are navigated when using just keyboard (tabOrder)."
        },
        "visual": {
            "description": "Defines a chart to be shown inside of this container.",
            "$ref": "../../visualConfiguration/2.0.0/schema-embedded.json"
        },
        "visualGroup": {
            "description": "Defines that this container should be used as a grouping container.",
            "$ref": "#/definitions/VisualGroupConfig"
        },
        "parentGroupName": {
            "description": "Name of the parent group (visual container), if it is part of one.",
            "type": "string"
        },
        "filterConfig": {
            "description": "Filters that apply to all this visual - on top of the filters defined for the report and page.",
            "$ref": "../../filterConfiguration/1.1.0/schema-embedded.json"
        },
        "isHidden": {
            "description": "Marks the visual as hidden.",
            "type": "boolean"
        },
        "annotations": {
            "description": "Additional information to be saved (for example comments, readme, etc) for this visual.",
            "type": "array",
            "items": {
                "$ref": "#/definitions/Annotation"
            }
        },
        "howCreated": {
            "description": "Source of creation of this visual.",
            "type": "string",
            "anyOf": [
                {
                    "const": "Default",
                    "description": "Used when it doesn't fall in any of the buckets below."
                },
                {
                    "const": "Copilot",
                    "description": "Created by copilot."
                },
                {
                    "const": "CheckboxTickedInFieldList",
                    "description": "Selecting data from field list."
                },
                {
                    "const": "DraggedToCanvas",
                    "description": "Dragging data from field list to the canvas."
                },
                {
                    "const": "VisualTypeIconClicked",
                    "description": "Clicking a specific visual icon in visualizations list."
                },
                {
                    "const": "DraggedToFieldWell",
                    "description": "Dragging data from field list to field wells."
                },
                {
                    "const": "InsertVisualButton",
                    "description": "Clicking the \"Insert visual\" button in ribbon."
                },
                {
                    "const": "WhatIfParameterControl",
                    "description": "Automatically by what-if parameter."
                },
                {
                    "const": "QnaAppBar",
                    "description": "Ask a question in app bar."
                },
                {
                    "const": "QnaDoubleClick",
                    "description": "Double clicking on the canvas to generate a Q&A visual."
                },
                {
                    "const": "QnaKeyboardShortcut",
                    "description": "Use keyboard shortcut for Q&A visual."
                },
                {
                    "const": "FieldParameterControl",
                    "description": "Automatically by field parameters."
                },
                {
                    "const": "CanvasBackgroundContextMenu",
                    "description": "Using on-object context menu for the canvas."
                },
                {
                    "const": "ContextMenuPaste",
                    "description": "By using paste from context manu."
                },
                {
                    "const": "CopyPaste",
                    "description": "By using copy paste."
                },
                {
                    "const": "SummarizeVisualContainer",
                    "description": "By using context menu Summarize."
                }
            ]
        }
    },
    "additionalProperties": false,
    "required": [
        "$schema",
        "name",
        "position"
    ],
    "definitions": {
        "VisualContainerPosition": {
            "type": "object",
            "properties": {
                "x": {
                    "description": "Horizontal position of the left edge of the visual.\nShould be between 0 and width of the containing page.",
                    "type": "number"
                },
                "y": {
                    "description": "Vertical position of the top edge of the visual.\nShould be between 0 and height of the containing page.",
                    "type": "number"
                },
                "z": {
                    "description": "Defines the stacking order for the visual.\nHigher z-index visuals are shown on top of the lower ones.",
                    "type": "number"
                },
                "height": {
                    "description": "Height of the visual.\ny + height should be less than the height of the containing page.",
                    "type": "number"
                },
                "width": {
                    "description": "Width of the visual.\nx + width should be less than the width of the containing page.",
                    "type": "number"
                },
                "tabOrder": {
                    "description": "Defines the selection order for this visual when using keyboard (tab key)\nto navigate the visuals on the containing page.",
                    "type": "number"
                },
                "angle": {
                    "type": "number"
                }
            },
            "additionalProperties": false,
            "required": [
                "height",
                "width",
                "x",
                "y"
            ]
        },
        "VisualGroupConfig": {
            "type": "object",
            "properties": {
                "displayName": {
                    "description": "Display name for the group.",
                    "type": "string"
                },
                "groupMode": {
                    "$ref": "#/definitions/GroupLayoutMode",
                    "description": "Defines how the visuals are organized inside this group."
                },
                "objects": {
                    "description": "Specifies the formatting to be set for different \"objects\" of this group.",
                    "$ref": "#/definitions/VisualGroupFormattingObjects"
                }
            },
            "additionalProperties": false,
            "required": [
                "displayName",
                "groupMode"
            ]
        },
        "GroupLayoutMode": {
            "type": "string",
            "anyOf": [
                {
                    "const": "ScaleMode",
                    "description": "Visuals are scaled as group resizes to preserve the aspect ratio and avoid scrolling."
                },
                {
                    "const": "ScrollMode",
                    "description": "Visuals are not resized, if the containing box for group is smaller than the space\nneeded for visuals, then scrollbar is added."
                }
            ]
        },
        "VisualGroupFormattingObjects": {
            "type": "object",
            "properties": {
                "background": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "selector": {
                                "description": "Defines the scope at which to apply the formatting for this object.\nCan also define rules for matching highlighted values and how multiple definitions for the same property should be ordered.",
                                "$ref": "../../formattingObjectDefinitions/1.3.0/schema.json#/definitions/Selector"
                            },
                            "properties": {
                                "$ref": "../../visualConfiguration/2.0.0/schema-embedded.json#/definitions/Background",
                                "description": "Describes the properties of the object to apply formatting changes to."
                            }
                        },
                        "additionalProperties": false,
                        "required": [
                            "properties"
                        ]
                    }
                },
                "lockAspect": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "selector": {
                                "description": "Defines the scope at which to apply the formatting for this object.\nCan also define rules for matching highlighted values and how multiple definitions for the same property should be ordered.",
                                "$ref": "../../formattingObjectDefinitions/1.3.0/schema.json#/definitions/Selector"
                            },
                            "properties": {
                                "$ref": "../../visualConfiguration/2.0.0/schema-embedded.json#/definitions/LockAspect",
                                "description": "Describes the properties of the object to apply formatting changes to."
                            }
                        },
                        "additionalProperties": false,
                        "required": [
                            "properties"
                        ]
                    }
                },
                "general": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "selector": {
                                "description": "Defines the scope at which to apply the formatting for this object.\nCan also define rules for matching highlighted values and how multiple definitions for the same property should be ordered.",
                                "$ref": "../../formattingObjectDefinitions/1.3.0/schema.json#/definitions/Selector"
                            },
                            "properties": {
                                "$ref": "#/definitions/VisualGroupGeneralFormattingObjects",
                                "description": "Describes the properties of the object to apply formatting changes to."
                            }
                        },
                        "additionalProperties": false,
                        "required": [
                            "properties"
                        ]
                    }
                }
            },
            "additionalProperties": false
        },
        "VisualGroupGeneralFormattingObjects": {
            "type": "object",
            "properties": {
                "x": {},
                "y": {},
                "width": {},
                "height": {},
                "altText": {}
            },
            "additionalProperties": false
        },
        "Annotation": {
            "type": "object",
            "properties": {
                "name": {
                    "description": "Unique name for the annotation.",
                    "type": "string"
                },
                "value": {
                    "description": "A value for this annotation.",
                    "type": "string"
                }
            },
            "additionalProperties": false,
            "required": [
                "name",
                "value"
            ]
        }
    },
    "oneOf": [
        {
            "required": [
                "visual"
            ]
        },
        {
            "required": [
                "visualGroup"
            ]
        }
    ]
}

{
    "$id": "https://developer.microsoft.com/json-schemas/fabric/item/report/definition/filterConfiguration/1.1.0/schema.embedded.json",
    "$schema": "http://json-schema.org/draft-07/schema#",
    "title": "Filter configuration",
    "description": "Defines the configuration of filters.",
    "type": "object",
    "properties": {
        "filters": {
            "description": "Defines the definitions and metadata for the filters.",
            "type": "array",
            "items": {
                "$ref": "#/definitions/FilterContainer"
            }
        },
        "filterSortOrder": {
            "description": "Defines how the filters sorted - by name or custom sorting\nIf custom sorting, then ordinal property of every filter is used as the sort order,\nfilters where ordinal is skipped will be shown at the end; ordering will fallback to display name of the field.",
            "type": "string",
            "anyOf": [
                {
                    "const": "Ascending",
                    "description": "Sorted ascending by display name of the filter field."
                },
                {
                    "const": "Descending",
                    "description": "Sorted descending by display name of the filter field."
                },
                {
                    "const": "Custom",
                    "description": "Sorted ascending by ordinal property of filters."
                }
            ]
        }
    },
    "additionalProperties": false,
    "definitions": {
        "FilterContainer": {
            "type": "object",
            "properties": {
                "name": {
                    "description": "A unique name (across the whole report definition) defined for this filter.",
                    "type": "string"
                },
                "displayName": {
                    "description": "An alternate name to use when displaying this filter - by default the display name of the field will be used, if there is no field or display name,\nthen restatement of the filter will be shown. Only applies to certain filter types.",
                    "type": "string"
                },
                "ordinal": {
                    "description": "Defines the ordering of this filter w.r.t. other filters - only applies when Custom sort order is set.",
                    "type": "number"
                },
                "field": {
                    "description": "Defines the field from your data that is filtered.",
                    "$ref": "../../semanticQuery/1.2.0/schema.json#/definitions/QueryExpressionContainer"
                },
                "type": {
                    "description": "The type of a filter.",
                    "type": "string",
                    "anyOf": [
                        {
                            "const": "Categorical"
                        },
                        {
                            "const": "Range"
                        },
                        {
                            "const": "Advanced"
                        },
                        {
                            "const": "Passthrough"
                        },
                        {
                            "const": "TopN"
                        },
                        {
                            "const": "Include"
                        },
                        {
                            "const": "Exclude"
                        },
                        {
                            "const": "RelativeDate"
                        },
                        {
                            "const": "Tuple"
                        },
                        {
                            "const": "RelativeTime"
                        },
                        {
                            "const": "VisualTopN"
                        }
                    ]
                },
                "filter": {
                    "description": "Defines the actual filter definition - it is dependent on the type of filter.",
                    "$ref": "../../semanticQuery/1.2.0/schema.json#/definitions/FilterDefinition"
                },
                "restatement": {
                    "description": "A custom restatement to show for the filter - only applies to Passthrough filter type. For all other filters, a restatement is generated based on the filter definition.",
                    "type": "string"
                },
                "howCreated": {
                    "description": "Specifies how this filter was first created.",
                    "type": "string",
                    "anyOf": [
                        {
                            "const": "Auto",
                            "description": "Created automatically when a field is used in the visual."
                        },
                        {
                            "const": "User",
                            "description": "Filters created from fields not used in a visual by the user."
                        },
                        {
                            "const": "Drill",
                            "description": "Created when drilling down on a data point in a visual."
                        },
                        {
                            "const": "Include",
                            "description": "Created by including a data point in a visual."
                        },
                        {
                            "const": "Exclude",
                            "description": "Created by excluding a data point from a visual."
                        },
                        {
                            "const": "Drillthrough",
                            "description": "Created by drill context that is applied to the page when using drill-through\naction from another page."
                        }
                    ]
                },
                "isHiddenInViewMode": {
                    "description": "Defines whether to hide this filter when viewing the report.",
                    "type": "boolean"
                },
                "isLockedInViewMode": {
                    "description": "Defines whether the filter value can be changed when viewing the report.",
                    "type": "boolean"
                },
                "objects": {
                    "description": "Formatting for different \"objects\" of a filter card",
                    "$ref": "#/definitions/FilterContainerFormattingObjects"
                }
            },
            "additionalProperties": false,
            "required": [
                "name"
            ]
        },
        "FilterContainerFormattingObjects": {
            "type": "object",
            "properties": {
                "general": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "selector": {
                                "description": "Defines the scope at which to apply the formatting for this object.\nCan also define rules for matching highlighted values and how multiple definitions for the same property should be ordered.",
                                "$ref": "../../formattingObjectDefinitions/1.3.0/schema.json#/definitions/Selector"
                            },
                            "properties": {
                                "$ref": "#/definitions/FilterContainerFormattingObjectsProperties",
                                "description": "Describes the properties of the object to apply formatting changes to."
                            }
                        },
                        "additionalProperties": false,
                        "required": [
                            "properties"
                        ]
                    }
                }
            },
            "additionalProperties": false
        },
        "FilterContainerFormattingObjectsProperties": {
            "type": "object",
            "properties": {
                "requireSingleSelect": {},
                "isInvertedSelectionMode": {}
            },
            "additionalProperties": false
        }
    }
}

{
    "$id": "https://developer.microsoft.com/json-schemas/fabric/item/report/definition/formattingObjectDefinitions/1.3.0/schema.json",
    "$schema": "http://json-schema.org/draft-07/schema#",
    "title": "Formatting Object Definitions",
    "description": "Defines shared definitions for report object formatting.",
    "definitions": {
        "DataViewObjectDefinitions": {
            "type": "object",
            "additionalProperties": {
                "type": "array",
                "items": {
                    "$ref": "#/definitions/DataViewObjectDefinition"
                }
            }
        },
        "DataViewObjectDefinition": {
            "type": "object",
            "properties": {
                "selector": {
                    "$ref": "#/definitions/Selector"
                },
                "properties": {
                    "$ref": "#/definitions/DataViewObjectPropertyDefinitions"
                }
            },
            "additionalProperties": false,
            "required": [
                "properties"
            ]
        },
        "DataViewObjectPropertyDefinitions": {
            "type": "object",
            "additionalProperties": {}
        },
        "Selector": {
            "type": "object",
            "properties": {
                "data": {
                    "description": "Scope is defined by data bound to the visual.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/DataRepetitionSelector"
                    }
                },
                "metadata": {
                    "description": "Defines the scope to a specific field.",
                    "type": "string"
                },
                "id": {
                    "description": "User defined scope.",
                    "type": "string"
                },
                "highlightMatching": {
                    "description": "Describes how the Selector should behave towards Highlighted Values within the Scope matched by that Selector.",
                    "default": "ValuesOnly",
                    "type": "number",
                    "anyOf": [
                        {
                            "const": 0,
                            "description": "Only non-highlighted value will be selected, even if a highlighted value exists."
                        },
                        {
                            "const": 1,
                            "description": "Non-highlighted values are selected. If highlighted values exist, they are selected as well."
                        },
                        {
                            "const": 2,
                            "description": "If a highlighted value exists, it's selected. Otherwise, the non-highlighted value is selected."
                        }
                    ]
                },
                "hierarchyMatching": {
                    "description": "Describes how the selector matches hierarchy values.\nThis also changes how the query is generated for {@link DataViewScopeWildcard} selectors.\nNow those selectors can produce scopedValues for the level those match.\n\nThere are two ways that we can match values in the hierarchy:\n1.",
                    "default": "`HierarchyMatching.Full` - Only leaf levels are matched.\r\nUses the values array which exits only for the last level {@link DataViewMatrixNode.values }\r\n\r\n2. {@link `HierarchyMatching.Partial`} - Can match any specific level. Which works two different ways:\r\n\r\n- Getting the value from the subtotal if we match the whole hierarchy.\r\n\r\n- Getting the value from scoped values if match specific level {@link DataViewMatrixNode.nodeValues }.\r\n\r\n(Using {@link DataViewScopeWildcard }).",
                    "type": "number",
                    "anyOf": [
                        {
                            "const": 0,
                            "description": "Only leaf levels are matched."
                        },
                        {
                            "const": 1,
                            "description": "All levels are matched."
                        }
                    ]
                },
                "order": {
                    "description": "Specifies a user-defined ordering of identical properties.\nSelector constructors should strive to monitonically increase this number across identical properties differing by id.",
                    "type": "number"
                }
            },
            "additionalProperties": false
        },
        "DataRepetitionSelector": {
            "type": "object",
            "properties": {
                "scopeId": {
                    "description": "Defines the intersection of scopes. For example - product color = red.",
                    "$ref": "../../semanticQuery/1.2.0/schema.json#/definitions/QueryExpressionContainer"
                },
                "wildcard": {
                    "description": "Defines a match against all instances of a given DataView scope. Does not match Subtotals.\nDeprecated: - Use roles instead.",
                    "type": "array",
                    "items": {
                        "$ref": "../../semanticQuery/1.2.0/schema.json#/definitions/QueryExpressionContainer"
                    }
                },
                "roles": {
                    "description": "Matches against all fields in a role.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "total": {
                    "description": "Matches against the totals and subtotals.",
                    "type": "array",
                    "items": {
                        "$ref": "../../semanticQuery/1.2.0/schema.json#/definitions/QueryExpressionContainer"
                    }
                },
                "dataViewWildcard": {
                    "description": "Matches all instances or all totals or both.",
                    "$ref": "#/definitions/DataViewWildcard"
                }
            },
            "additionalProperties": false
        },
        "DataViewWildcard": {
            "type": "object",
            "properties": {
                "matchingOption": {
                    "$ref": "#/definitions/DataViewWildcardMatchingOption",
                    "description": "Defines the matching option to use."
                }
            },
            "additionalProperties": false,
            "required": [
                "matchingOption"
            ]
        },
        "DataViewWildcardMatchingOption": {
            "type": "number",
            "anyOf": [
                {
                    "const": 0,
                    "description": "Match Identities and Totals (default)"
                },
                {
                    "const": 1,
                    "description": "Match Instances with Identities only"
                },
                {
                    "const": 2,
                    "description": "Match Totals only"
                }
            ]
        }
    }
}

{
    "$id": "https://developer.microsoft.com/json-schemas/fabric/item/report/definition/semanticQuery/1.0.0/schema.json",
    "$schema": "http://json-schema.org/draft-07/schema#",
    "title": "Semantic Query",
    "description": "Defines shared definitions for queries and filters.",
    "definitions": {
        "FilterDefinition": {
            "description": "Defines a filter element as a partial query structure",
            "type": "object",
            "properties": {
                "Version": {
                    "description": "Version of the query",
                    "type": "number",
                    "const": 2
                },
                "From": {
                    "description": "Set of tables from which the data will be picked.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/EntitySource"
                    }
                },
                "Where": {
                    "description": "Set of filters to apply to the data.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/QueryFilter"
                    }
                }
            },
            "additionalProperties": false,
            "required": [
                "From",
                "Where"
            ]
        },
        "QueryFilter": {
            "type": "object",
            "properties": {
                "Target": {
                    "description": "Set of expressions over which the condition applies. Applied to the set of all non-aggregate, non-measure expressions in the Select if not specified.",
                    "type": "array",
                    "items": {
                        "$ref": "#/definitions/QueryExpressionContainer"
                    }
                },
                "Condition": {
                    "$ref": "#/definitions/QueryExpressionContainer",
                    "description": "Condition to apply to the target. Must be an expression that evaluates to a boolean."
                },
                "Annotations": {
                    "description": "Auxillary metadata for this filter.",
                    "type": "object",
                    "additionalProperties": {}
                }
            },
            "additionalProperties": false,
            "required": [
                "Condition"
            ]
        },
        "QueryExpressionContainer": {
            "description": "Holds a single expression and associated metadata. \nName, NativeReferenceName, and Annotations may be specified for any expression.\nEach other property represents a specific type of expression and exactly one of these other properties must be specified.",
            "type": "object",
            "properties": {
                "Name": {
                    "description": "The name by which the expression can be referenced",
                    "type": "string"
                },
                "NativeReferenceName": {
                    "description": "The name by which the expression can be referenced in native expressions.",
                    "type": "string"
                },
                "Annotations": {
                    "description": "Auxiliary metadata for this expression.",
                    "type": "object",
                    "additionalProperties": {}
                },
                "SourceRef": {
                    "description": "The SourceRef element contains an expression which is reference to a source table in the query or the data.",
                    "anyOf": [
                        {
                            "$ref": "#/definitions/StandaloneSourceRefExpression"
                        },
                        {
                            "$ref": "#/definitions/QuerySourceRefExpression"
                        }
                    ]
                },
                "Column": {
                    "description": "The Column element contains an expression which is a reference to a column in a source table.",
                    "$ref": "#/definitions/QueryColumnExpression"
                },
                "Measure": {
                    "description": "The Measure element contains an expression which is a reference to a measure in a source table.",
                    "$ref": "#/definitions/QueryMeasureExpression"
                },
                "Min": {
                    "description": "The Min element contains an expression whose min aggregation needs to be computed.",
                    "$ref": "#/definitions/QueryMinExpression"
                },
                "Max": {
                    "description": "The Max element contains an expression whose max aggregation needs to be computed.",
                    "$ref": "#/definitions/QueryMaxExpression"
                },
                "Aggregation": {
                    "description": "The Aggregation element contains an expression which is an aggregation of an expression.",
                    "$ref": "#/definitions/QueryAggregationExpression"
                },
                "Percentile": {
                    "description": "The Percentile element contains an expression which computes a percentile of an expression.",
                    "$ref": "#/definitions/QueryPercentileExpression"
                },
                "Hierarchy": {
                    "description": "Hierarchy is an element which represents a reference to a hierarchy in a source table.",
                    "$ref": "#/definitions/QueryHierarchyExpression"
                },
                "HierarchyLevel": {
                    "description": "HierarchyLevel is an element which represents a reference to a hierarchy level in a hierarchy.",
                    "$ref": "#/definitions/QueryHierarchyLevelExpression"
                },
                "PropertyVariationSource": {
                    "description": "PropertyVariationSource is an element which represents a reference to a source of variations associated with a property.",
                    "$ref": "#/definitions/QueryPropertyVariationSourceExpression"
                },
                "Subquery": {
                    "description": "Subquery is an element which holds a query.",
                    "$ref": "#/definitions/QuerySubqueryExpression"
                },
                "Discretize": {
                    "description": "Transforms a continuous space of numerical values into a discrete space of numerical values.",
                    "$ref": "#/definitions/QueryDiscretizeExpression"
                },
                "And": {
                    "description": "The And element contains an expression which represents an \"and\" between two expressions that evaluate to a boolean value.",
                    "$ref": "#/definitions/QueryBinaryExpression"
                },
                "Between": {
                    "description": "The Between element contains an expression which is a comparison between an expression and two bounds.",
                    "$ref": "#/definitions/QueryBetweenExpression"
                },
                "In": {
                    "description": "The In element contains an expression which is a comparison between an ordered list of expressions and a set of ordered lists of values.\nIf the tuple defined in Expressions matches any tuple defined in Values, then In returns true.",
                    "$ref": "#/definitions/QueryInExpression"
                },
                "Or": {
                    "description": "The And element contains an expression which represents an \"or\" between two expressions that evaluate to a boolean value.",
                    "$ref": "#/definitions/QueryBinaryExpression"
                },
                "Comparison": {
                    "description": "The Comparison element contains an expression which is a comparison between two expressions.",
                    "$ref": "#/definitions/QueryComparisonExpression"
                },
                "Not": {
                    "description": "The Not element contains an expression which represents a \"not\" of an expression that evaluate to a boolean value.",
                    "$ref": "#/definitions/QueryNotExpression"
                },
                "Contains": {
